export const riverTopic={id:'geography.a.rivers',title:'River landscapes and processes',discipline:'Physical geography'};
const q=(u,n,prompt,options,answer,why,concept)=>({id:`geo.a.r1.${u}.${n}`,prompt,options,answer,why,concept:'geo.a.river.'+concept});
const make=(slug,title,refs,cards,tasks,practice,check,model)=>({id:'geography.a.rivers.'+slug,topicId:riverTopic.id,option:'rivers',title,refs,cards,tasks,practice,check,model,minutes:25});
export const riverLessons=[
make('slopes','Weathering and river-valley slopes',['1.7a'],[
 ['Break down in place','Mechanical weathering breaks rock physically: water can freeze and expand in cracks over repeated cycles. Chemical reactions can alter or dissolve susceptible minerals. Biological activity such as root growth can widen weaknesses. Weathering prepares loose material without itself requiring transport down the river.'],
 ['Gravity takes over','A slide moves material along a broadly planar surface; a rotational slump turns along a curved slip surface. Both transfer material downslope under gravity. The valley side supplies sediment to a channel, where flowing water may later transport it. A slump is not the same movement as a bouncing sand grain.'],
 ['An interacting valley','Heavy rain may saturate slopes, increase loading and pore-water pressure and reduce resistance. River erosion can undercut the slope toe, removing support. Weathering can weaken rock. Failure depends on the balance of forces and local conditions; not every rain event causes a landslide.']
],[['Predict: roots widen a valley-side crack without moving material downstream. This is…',['Biological weathering','River traction','Longshore drift'],0],['Compare slide and slump. Curved slip with rotation identifies…',['A slump','A planar slide','Dissolved load'],0],['A river removes support at a bank’s toe. This can…',['Encourage slope instability','Guarantee every slope becomes stable','Remove gravity'],0],['Sediment falls into a river after weathering. The two stages show…',['Breakdown followed by gravity-driven transfer','Only chemical dissolution','No interaction between slope and channel'],0]],
[q('slope','p1','Repeated freezing of water in cracks is…',['Mechanical weathering','Saltation','Deposition'],0,'Expansion during repeated freeze–thaw can widen cracks in place.','weathering'),q('slope','p2','Which movement follows a relatively flat slip surface?',['Sliding','Rotational slumping','Suspension'],0,'Sliding is distinguished here by a broadly planar surface.','mass-movement'),q('slope','p3','Why can saturation affect slope stability?',['It can increase loading and water pressure','It always removes gravity','It always stops river erosion'],0,'Saturation can change forces and resistance; failure is not automatic.','saturation')],
[q('slope','c1','Minerals react chemically with water in a valley-side rock. This is…',['Chemical weathering','Traction','A river flood by definition'],0,'Chemical weathering alters minerals in place.','weathering'),q('slope','c2','A block rotates along a curved failure surface. This is…',['Rotational slumping','Saltation','Solution'],0,'The whole mass moves and rotates, unlike individual transported grains.','mass-movement'),q('slope','c3','River undercutting can contribute to failure by…',['Removing support at the slope toe','Stopping every weathering process','Making every bank identical'],0,'Reduced support can combine with other destabilising factors.','slope-channel'),q('slope','c4','Which avoids an unsupported claim?',['Saturation may increase instability, depending on conditions','Every wet slope must collapse','Rain never affects slopes'],0,'Explain a conditional mechanism rather than a universal outcome.','saturation')],'river-slopes'),
make('sediment','How rivers erode and carry sediment',['1.7a'],[
 ['Identify the target','Hydraulic action is water force acting on weaknesses. Abrasion is carried sediment scraping or striking the bed and banks. Attrition occurs when particles collide, becoming smaller and rounder. Solution involves dissolving susceptible material. Abrasion attacks the channel; attrition wears the transported particles.'],
 ['Track the load','Large grains may roll or slide along the bed: traction. Some grains bounce: saltation. Fine solids are carried within the water: suspension. Dissolved material travels in solution, not as visible grains. Which load a river can carry depends on flow conditions, grain properties and supply.'],
 ['When the load is left','A fall in transport capacity can cause deposition of some of the load. Coarser material often settles before fine material as flow weakens, but grain shape and other conditions matter. Deposition does not mean the entire river has stopped moving. Erosion, transport and deposition can occur in different parts of one reach.']
],[['Predict: pebbles scrape a bank. Which process targets the bank?',['Abrasion','Attrition','Root growth'],0],['Compare load views. Grains bouncing over the bed show…',['Saltation','Suspension','Chemical weathering'],0],['A weaker flow cannot carry some of its gravel. It may…',['Deposit that gravel','Turn it instantly into dissolved ions','Stop all water everywhere'],0],['Two pebbles collide and become rounder. This is…',['Attrition','Only bank abrasion','Biological weathering'],0]],
[q('load','p1','Water force enlarges a crack in a river bank. This is…',['Hydraulic action','Traction','Evapotranspiration'],0,'Water force can exploit channel weaknesses.','erosion'),q('load','p2','Fine solid particles carried within water are in…',['Suspension','Traction','Only solution'],0,'Suspended load remains solid; dissolved load is chemically in the water.','transport'),q('load','p3','Why can slower flow lead to deposition?',['Transport capacity for some material falls','Gravity has disappeared','Every grain becomes granite'],0,'Some material can no longer be carried under the changed conditions.','deposition')],
[q('load','c1','Rounding of colliding sediment particles identifies…',['Attrition','Only hydraulic action','Plant growth'],0,'The particles themselves are worn by collisions.','erosion'),q('load','c2','A boulder rolling along the bed is moved by…',['Traction','Suspension','Dissolved transport'],0,'Traction keeps the load in contact with the bed.','transport'),q('load','c3','Which statement about dissolved load is correct?',['It travels in solution rather than as visible solid grains','It is always a large rolling boulder','It cannot move in water'],0,'Dissolved substances differ from suspended solids.','solution'),q('load','c4','Deposition in one part of a reach means…',['Some material is being laid down there','The whole river must have stopped','No erosion can occur anywhere else'],0,'Processes can coexist and vary within a reach.','deposition')],'river-load'),
make('downstream','From upland valleys to lowland channels',['1.7b','Integrated skill 9: introductory'],[
 ['Two profiles, two questions','A long profile follows the river from source to mouth, showing how height and gradient change along its length. A valley cross-profile cuts across the valley; a channel cross-section cuts across the water channel. Do not use the width of the whole valley as the width of flowing water.'],
 ['Broad downstream tendencies','Upper-course valleys are often narrow and steep-sided, with steeper channel gradients and important vertical erosion. Downstream, valley floors commonly broaden and channels generally become wider and deeper as tributaries add water. Lateral erosion and deposition can become more prominent. These are broad comparisons, not guaranteed changes at every point.'],
 ['Explain exceptions','Rock structure, resistant outcrops, tributaries, dams, channel engineering and changing flow can interrupt a simple profile. A river’s average gradient may decline downstream without every reach being flatter than the one before. Use mapped and measured evidence for a named river; our sections are original teaching comparisons, not surveyed Tees profiles.']
],[['Predict: tributaries add water downstream. Channels often become…',['Wider and deeper overall','Narrower and shallower at every single point','Identical regardless of flow'],0],['Compare the valley and channel sections. The whole valley’s width is…',['Not the same measurement as wetted channel width','Always exactly channel width','The same as water speed'],0],['Which view follows height along the river’s route?',['The long profile','Only a cross-valley section','A population pyramid'],0],['A resistant rock step interrupts a river profile. This shows…',['Local geology can produce exceptions','All downstream trends are meaningless','Every river has identical steps'],0]],
[q('profile','p1','A long profile primarily shows…',['Height and gradient along the river course','Only the width across one channel','Only today’s rainfall'],0,'It follows the river longitudinally.','profiles'),q('profile','p2','A broader lower-course valley can reflect…',['Lateral erosion and deposition over time','The absence of all past river activity','Only a change in rock colour'],0,'Landscapes record interacting processes and history.','downstream'),q('profile','p3','Which is a defensible downstream comparison?',['Channels tend to become wider/deeper, with local exceptions','Every downstream metre must be wider','All tributaries remove water'],0,'Use general patterns with evidence and qualifications.','downstream')],
[q('profile','c1','A cut across the valley rather than along the river is a…',['Cross-profile','Long profile','Rainfall total'],0,'Orientation determines what the profile represents.','profiles'),q('profile','c2','Vertical erosion is commonly important in…',['Steeper upper-course reaches','Only the sea beyond the mouth','No river reach'],0,'Downcutting is associated with many upper-course settings.','downstream'),q('profile','c3','Which may interrupt a simple downstream pattern?',['Geology, tributaries or engineering','Only the name printed on a map','The existence of a map key'],0,'Local controls can modify channels and profiles.','profile-controls'),q('profile','c4','To establish actual Tees gradients and rock relationships, you need…',['Appropriate mapped geology and profile evidence','Only these invented sections','Only another river’s name'],0,'The model introduces relationships but is not a measured or BGS-map dataset.','map-evidence')],'river-courses'),
make('tees-flow','The Tees: discharge, speed and sediment',['1.7b'],[
 ['Locate a named river','The Tees rises on Cross Fell in the North Pennines and reaches the North Sea between Hartlepool and Redcar. Follow the idea of an upland source, middle reaches and lower Tees into its estuary. The lower river has been modified for navigation, so do not assume every reach is an unaltered textbook pattern.'],
 ['Volume is not speed','Discharge is the volume passing a cross-section each second: Q = cross-sectional area × mean velocity. For an invented reach, area 8m² × mean velocity 0.5m/s = 4m³/s. Double area at the same speed and discharge doubles; double speed at the same area and it also doubles. Width × mean depth can estimate area; one centre-depth reading is not the mean. These numbers are not Tees measurements.'],
 ['Connect, then qualify','Downstream, tributary inputs commonly increase discharge, and channels tend to become larger and more efficient. Average velocity can increase despite a gentler gradient as relative friction decreases; local conditions still matter. Transport and attrition tend to make bed material smaller and rounder, while new tributary inputs or geology can add fresh coarse load. The Tees example locates these ideas; actual changes need comparable field or map evidence.']
],[['Predict: double area while mean speed stays the same. Discharge…',['Doubles','Halves','Must stay unchanged'],0],['Compare base and faster flow. Same area but twice the speed gives…',['Twice the discharge','Half the discharge','No change in volume per second'],0],['In the teaching model, 8m² ×0.5m/s equals…',['4m³/s','16m³/s','4m/s'],0],['Which Tees statement is supported by the location source?',['It reaches the North Sea','It is a river in southern Spain','Its source is the sea'],0]],
[q('flow','p1','Teaching reach: area 12m², mean speed 0.5m/s. Discharge?',['6m³/s','24m³/s','6m/s'],0,'Q=12×0.5=6m³/s. Volume per time differs from velocity.','discharge'),q('flow','p2','Why can lower-course speed increase despite a gentler gradient?',['Larger channels can have less friction relative to water volume','Gradient is the only control','Every lower reach must be faster'],0,'Channel efficiency and other controls affect speed; the pattern is not universal.','velocity'),q('flow','p3','Bed material often becomes rounder downstream because…',['Particles collide and wear during transport','Every grain melts','All downstream rock is identical'],0,'Attrition can round material, with local supply exceptions.','sediment-change')],
[q('flow','c1','Teaching reach: area 6m², mean speed 0.5m/s. Discharge?',['3m³/s','12m³/s','3m/s'],0,'6×0.5=3m³/s; retain the discharge units.','discharge'),q('flow','c2','The Tees’ source is associated with…',['Cross Fell in the North Pennines','Swanage Bay','The mouth of the Thames'],0,'Location is verified separately from the invented calculation values.','tees-location'),q('flow','c3','A tributary brings fresh angular gravel. This means…',['Sediment trends can have local exceptions','Attrition never occurs','All river evidence is useless'],0,'New inputs can interrupt a general downstream size/roundness pattern.','sediment-change'),q('flow','c4','Which correctly distinguishes discharge and velocity?',['Discharge is volume/time; velocity is distance/time','Both are measured only in metres','Water level directly gives both without calibration'],0,'Q uses m³/s; velocity uses m/s, and stage is a different measure.','discharge')],'river-flow'),
make('weather','Rain, drought and river response',['1.7c','Integrated skill 10: introductory'],[
 ['A catchment responds','Rain falling on a catchment can reach a channel by surface runoff and slower soil/groundwater pathways. Intense or prolonged rain can increase discharge, especially when soils are already saturated. The river’s response can lag behind rainfall. The same rainfall need not produce the same response in every catchment.'],
 ['Short events and longer patterns','Storms can increase erosion and transport, saturate slopes and raise flood likelihood. Prolonged dry weather and evapotranspiration can reduce available water and river flow, affecting sediment movement and habitats. Weather describes events; climate describes longer-term patterns. Soil, geology, storage, season and human management modify responses.'],
 ['Read a real gauge carefully','The EA Barnard Castle page for the Tees lists historical instantaneous stage values: 3.092m on 23 December 2013 and 0.297m on 4 September 2017. They are two dated observations, not live readings or a continuous graph. Stage is height relative to a gauge datum, not automatically full channel depth or discharge. These values alone cannot reveal the rainfall that caused a particular event, an annual mean or a climate trend.']
],[['Predict: otherwise comparable rain falls on already saturated ground. Quick runoff may…',['Increase','Always vanish','Become completely unrelated to catchment conditions'],0],['Compare rain and drought views. Prolonged dry weather can…',['Reduce river flow','Guarantee all rivers rise','Prove all rain has stopped forever'],0],['The genuine EA excerpt uses metres for instantaneous stage. It measures…',['Water level relative to a gauge datum','Volume passing per second directly','Annual rainfall'],0],['Two extreme stage values from different dates can establish…',['Those reported levels, not the causes or an annual mean','The exact rain totals for both events','Every future flood date'],0]],
[q('rain','p1','Why might rain and the highest river response occur at different times?',['Water takes time to travel through the catchment','Every river responds instantly everywhere','Gravity switches off at night'],0,'Different pathways and storage can delay response.','catchment-response'),q('rain','p2','Which is a climate statement rather than one weather event?',['A long-term seasonal pattern in rainfall','Rain at one time yesterday','A single afternoon storm'],0,'Climate concerns longer-term patterns and distributions.','weather-climate'),q('rain','p3','A stage reading of 3.092m alone tells you…',['A gauge-referenced water level','Exactly3.092m³/s discharge','The full channel depth at every point'],0,'Stage needs context and a rating relationship before flow can be inferred.','gauge-evidence')],
[q('rain','c1','Which catchment condition can encourage a rapid response to heavy rain?',['Already saturated soils','A guarantee that all water is stored forever','Only the river’s name'],0,'Limited infiltration/storage can increase quick runoff.','catchment-response'),q('rain','c2','Read the EA excerpt. What is its quantity and unit?',['Instantaneous stage in metres','Discharge in m³/s','Monthly rainfall in mm'],0,'The source identifies water level, not discharge or rainfall.','gauge-evidence'),q('rain','c3','What would be needed to investigate a rainfall–river response for a real event?',['Comparable dated rainfall and river records with context','Only two historical extrema years apart','Only one place name'],0,'Causal investigation needs appropriate paired evidence, not an unsupported inference.','weather-evidence'),q('rain','c4','Why is lower flow possible during a prolonged dry spell?',['Less water enters the system while losses and storage effects matter','All flow must instantly become zero','Dry weather always increases discharge'],0,'Explain the water balance and conditions rather than an absolute rule.','drought')],'river-weather')
];
riverLessons.find(l=>l.model==='river-weather').check[1].gauge=true;
